old_push_guard = """    let current_remote = remote_head(client).await?;\n    let expected_id = expected_remote.map(|commit| commit.id.as_str());\n    let current_id = current_remote.as_ref().map(|commit| commit.id.as_str());\n    if current_id != expected_id {\n        anyhow::bail!(\n            \"Cloud Node provider HEAD changed during push: expected {} but found {}; retry synchronization\",\n            expected_id.unwrap_or(\"<empty>\"),\n            current_id.unwrap_or(\"<empty>\")\n        );\n    }\n    upload_head(client, local_head).await?;\n"""
new_push_guard = """    let current_remote = remote_head_state(client).await?;\n    let expected_id = expected_remote.map(|commit| commit.id.as_str());\n    let current_id = current_remote\n        .as_ref()\n        .map(|state| state.commit.id.as_str());\n    if current_id != expected_id {\n        anyhow::bail!(\n            \"Cloud Node provider HEAD changed during push: expected {} but found {}; retry synchronization\",\n            expected_id.unwrap_or(\"<empty>\"),\n            current_id.unwrap_or(\"<empty>\")\n        );\n    }\n    upload_head(\n        client,\n        local_head,\n        current_remote\n            .as_ref()\n            .and_then(|state| state.version.as_ref()),\n        current_remote.is_some(),\n    )\n    .await?;\n"""
sync = replace_once(sync, old_push_guard, new_push_guard, "provider push CAS guard")

old_remote_head = """async fn remote_head(client: &ProviderClient) -> anyhow::Result<Option<HistoryCommit>> {\n    let Some(bytes) = client.get(\"history/HEAD.json\").await? else {\n        return Ok(None);\n    };\n    let pointer: HeadPointer = serde_json::from_slice(&bytes)?;\n    validate_head_pointer(&pointer)?;\n    fetch_remote_commit(client, &pointer.commit)\n        .await?\n        .map(Some)\n        .ok_or_else(|| {\n            anyhow::anyhow!(\n                \"Cloud Node provider HEAD references missing commit {}\",\n                pointer.commit\n            )\n        })\n}\n\n"""
new_remote_head = """async fn remote_head(client: &ProviderClient) -> anyhow::Result<Option<HistoryCommit>> {\n    Ok(remote_head_state(client).await?.map(|state| state.commit))\n}\n\nasync fn remote_head_state(\n    client: &ProviderClient,\n) -> anyhow::Result<Option<RemoteHeadState>> {\n    let Some(object) = client.get_versioned(\"history/HEAD.json\").await? else {\n        return Ok(None);\n    };\n    let pointer: HeadPointer = serde_json::from_slice(&object.bytes)?;\n    validate_head_pointer(&pointer)?;\n    let commit = fetch_remote_commit(client, &pointer.commit)\n        .await?\n        .ok_or_else(|| {\n            anyhow::anyhow!(\n                \"Cloud Node provider HEAD references missing commit {}\",\n                pointer.commit\n            )\n        })?;\n    Ok(Some(RemoteHeadState {\n        commit,\n        version: object.version,\n    }))\n}\n\n"""
sync = replace_once(sync, old_remote_head, new_remote_head, "versioned remote HEAD")

old_upload_head = """async fn upload_head(client: &ProviderClient, commit: &HistoryCommit) -> anyhow::Result<()> {\n    let pointer = HeadPointer {\n        format_version: HISTORY_VERSION,\n        commit: commit.id.clone(),\n    };\n    client\n        .put(\n            \"history/HEAD.json\",\n            serde_json::to_vec(&pointer)?,\n            \"application/json\",\n        )\n        .await\n}\n\n"""
new_upload_head = """async fn upload_head(\n    client: &ProviderClient,\n    commit: &HistoryCommit,\n    expected_version: Option<&ProviderObjectVersion>,\n    expected_exists: bool,\n) -> anyhow::Result<()> {\n    let pointer = HeadPointer {\n        format_version: HISTORY_VERSION,\n        commit: commit.id.clone(),\n    };\n    client\n        .put_if_unchanged(\n            \"history/HEAD.json\",\n            serde_json::to_vec(&pointer)?,\n            \"application/json\",\n            expected_version,\n            expected_exists,\n        )\n        .await\n        .map(|_| ())\n}\n\n"""
