doc_path = Path("doc/cloud-node.md")
docs = doc_path.read_text()
old_docs = """Before replacing the mutable provider HEAD, Cloud Node re-reads it and verifies that it still matches the remote head used when synchronization was planned. If another writer moved the head, the push fails and must be retried rather than blindly publishing stale history. This is an application-level race guard; it is not advertised as a provider-native atomic compare-and-swap primitive.\n"""
new_docs = """Before replacing the mutable provider HEAD, Cloud Node re-reads it and verifies that it still matches the remote head used when synchronization was planned. Amazon S3 and Azure Blob then publish `HEAD.json` with ETag preconditions (`If-Match` for replacement and `If-None-Match: *` for first creation), while Google Cloud Storage uses the object's generation with `x-goog-if-generation-match` (generation `0` for first creation). Those providers therefore reject stale cross-machine writers atomically at the object store. Supabase Storage and the generic HTTP provider keep the application-level re-read guard because their configured object APIs do not expose a portable equivalent through this provider interface.\n"""
docs = replace_once(docs, old_docs, new_docs, "provider CAS docs")
doc_path.write_text(docs)
